#!/usr/bin/env bash
# deploy_alias_stage2.sh — TENANT ALIAS ALTYAPISI (additive) + kokpit dinamik tenant basligi.
#   1) server_container.mjs: session/me'ye tenantAlias (config.alias || sirket adi) + kokpit-data payload'a tenant{name,alias}
#   2) shells/kokpit.html + kokpit2.html: baslik "<tenant> Finans Kokpiti" (DATA.tenant'tan dinamik)
#   Mevcut auth mantigi DEGISMEZ (yalniz ekleme). build + force-recreate. AYRICA: seed_krb_alias.sql calistir (KRB->alias).
set -e
cd /opt/krb-assessment
TS=$(date +%s)
echo "" | base64 -d > /tmp/patch_tenant_alias.py
echo ""   | base64 -d > /tmp/patch_kokpit_payload.py
# server dosyasini bul
SRV=server_container.mjs; [ -f "$SRV" ] || SRV=$(find . -maxdepth 2 -name server_container.mjs | head -1)
[ -n "$SRV" ] && [ -f "$SRV" ] || { echo "HATA: server_container.mjs yok"; exit 1; }
echo "server: $SRV"; cp "$SRV" "$SRV.bak.$TS"
python3 /tmp/patch_tenant_alias.py "$SRV"
python3 /tmp/patch_kokpit_payload.py "$SRV"
node --check "$SRV" && echo "  ✓ server syntax ok" || { echo "HATA: server syntax"; exit 1; }
grep -q 'tenantAlias' "$SRV" && echo "  ✓ tenantAlias mevcut" || { echo "HATA: alias yok"; exit 1; }
# cockpit shells (her ikisi)
for F in shells/kokpit.html shells/kokpit2.html; do
  [ -f "$F" ] && cp "$F" "$F.bak.$TS"
  echo "" | base64 -d > "$F"
  grep -q 'TENANT_ALIAS_V1' "$F" && echo "  ✓ $F dinamik baslik" || { echo "HATA: $F"; exit 1; }
done
echo "=== docker build + recreate ==="
docker build -t krb-assessment:secure . >/tmp/build.log 2>&1 && echo "build ok" || { echo "BUILD HATASI:"; tail -20 /tmp/build.log; exit 1; }
docker compose up -d --force-recreate krb-assessment && echo "recreate ok"
echo "=== KRB alias seed (postgres) ==="
echo "" | base64 -d > /tmp/seed_krb_alias.sql
docker cp /tmp/seed_krb_alias.sql krb-assessment-postgres:/tmp/seed_krb_alias.sql 2>/dev/null || true
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -f /tmp/seed_krb_alias.sql || echo "NOT: seed_krb_alias.sql'i elle calistir (alias KRB atanamadi)."
echo "BITTI."
